package config

import "os"

// ApplyAliases applies additional environment variable aliases not generated by
// the Printing Press template. Call this immediately after config.Load().
//
// EXA_API_KEY is the community-standard Exa API key env var (used by the Exa
// official SDK, docs, and irona-chat's internal exa-cli.mjs). The generated
// CLI uses EXA_TOKEN — this alias ensures users with EXA_API_KEY set don't
// need to re-export under a different name.
func ApplyAliases(cfg *Config) {
	if cfg == nil {
		return
	}
	// Only apply if no credential has been resolved yet.
	if cfg.ExaToken == "" && cfg.AuthHeaderVal == "" && cfg.AccessToken == "" {
		if v := os.Getenv("EXA_API_KEY"); v != "" {
			cfg.ExaToken = v
			cfg.AuthSource = "env:EXA_API_KEY"
		}
	}
}
